window.__TOPIC_JS=window.__TOPIC_JS||{};window.__TOPIC_JS["ことわざ"]={
"_note": "08. ことわざ — mỗi mục một dòng. LEVEL: p1 → p3 = 3 nhóm của chuyên đề (giữ nguyên nhãn gốc). THỨ TỰ: các nhóm xếp p1, p2, p3, không trộn lẫn; trong mỗi nhóm giữ nguyên thứ tự gốc. ĐỊNH DẠNG MỖI TỪ: word, reading, meaning, note (tuỳ chọn), example, example_reading, example_meaning, level. TRƯỜNG antonym (tuỳ chọn): từ trái nghĩa, dạng \"từ（cách đọc）: nghĩa\", nhiều từ cách nhau bằng \" / \". TRƯỜNG antonym_hanviet (tuỳ chọn, đi kèm antonym): âm Hán Việt của từng từ trái nghĩa, viết thường như trường hanviet, cùng thứ tự và cách nhau bằng \" / \" (từ chỉ có kana, không có chữ Hán, để trống). SỐ LƯỢNG: p1 70, p2 70, p3 60; tổng 200 mục.",
"id": "8. ことわざ",
"title": "ことわざ",
"icon": "📜",
"category": "ref",
"kind": "proverb",
"vocab": [
{"word":"猿も木から落ちる","reading":"さるもきからおちる","meaning":"khỉ cũng có lúc rơi khỏi cây → Thánh cũng có lúc lầm, nhân vô thập toàn","note":"⚠ Dễ nhầm với 河童の川流れ và 弘法にも筆の誤り (đều nghĩa 'người giỏi cũng sai'). 猿 dùng rộng nhất, cho mọi người giỏi một việc nào đó.","example":"有名なシェフが料理に失敗した。猿も木から落ちるね。","example_reading":"ゆうめいなシェフがりょうりにしっぱいした。さるもきからおちるね。","example_meaning":"Đầu bếp nổi tiếng cũng làm hỏng món. Khỉ cũng có lúc rơi cây nhỉ.","level":"p1"},
{"word":"七転び八起き","reading":"ななころびやおき","meaning":"ngã bảy lần, đứng dậy tám lần → Thất bại nhiều lần vẫn không bỏ cuộc","note":"⚠ Dễ nhầm với 石の上にも三年 và 継続は力なり. Câu này nhấn mạnh đứng dậy sau nhiều lần thất bại.","example":"七転び八起きの気持ちで、もう一度挑戦します。","example_reading":"ななころびやおきのきもちで、もういちどちょうせんします。","example_meaning":"Với tinh thần ngã bảy đứng dậy tám, tôi sẽ thử lại lần nữa.","level":"p1"},
{"word":"急がば回れ","reading":"いそがばまわれ","meaning":"muốn nhanh thì đi đường vòng → Dục tốc bất đạt","example":"近道より、急がば回れで安全な道を行こう。","example_reading":"ちかみちより、いそがばまわれであんぜんなみちをいこう。","example_meaning":"Thay vì đường tắt, hãy đi đường an toàn cho chắc.","level":"p1"},
{"word":"習うより慣れよ","reading":"ならうよりなれよ","meaning":"học không bằng làm quen → Thực hành quan trọng hơn lý thuyết","example":"日本語は習うより慣れよだから、毎日話そう。","example_reading":"にほんごはならうよりなれよだから、まいにちはなそう。","example_meaning":"Tiếng Nhật thì thực hành là chính, nên mỗi ngày hãy nói.","level":"p1"},
{"word":"継続は力なり","reading":"けいぞくはちからなり","meaning":"kiên trì là sức mạnh → Có công mài sắt có ngày nên kim","note":"⚠ Nhấn mạnh việc làm đều đặn, lâu dài sẽ ra kết quả. Khác 石の上にも三年 (chịu đựng lúc khó).","example":"継続は力なり。毎日十分でも勉強しよう。","example_reading":"けいぞくはちからなり。まいにちじゅっぷんでもべんきょうしよう。","example_meaning":"Kiên trì là sức mạnh. Mỗi ngày học 10 phút cũng được.","level":"p1"},
{"word":"千里の道も一歩から","reading":"せんりのみちもいっぽから","meaning":"đường ngàn dặm cũng bắt đầu từ một bước → Vạn sự khởi đầu nan","example":"千里の道も一歩から。まず今日の宿題を始めよう。","example_reading":"せんりのみちもいっぽから。まずきょうのしゅくだいをはじめよう。","example_meaning":"Đường ngàn dặm bắt đầu từ một bước. Trước hết làm bài tập hôm nay.","level":"p1"},
{"word":"案ずるより産むが易し","reading":"あんずるよりうむがやすし","meaning":"lo lắng không bằng bắt tay làm → Làm thử thường dễ hơn nghĩ","example":"面接は案ずるより産むが易しで、意外と簡単だった。","example_reading":"めんせつはあんずるよりうむがやすしで、いがいとかんたんだった。","example_meaning":"Phỏng vấn lo trước thì hóa ra lại dễ hơn nghĩ.","level":"p1"},
{"word":"石の上にも三年","reading":"いしのうえにもさんねん","meaning":"ngồi trên đá ba năm cũng ấm → Kiên nhẫn rồi sẽ thành","note":"⚠ Nhấn mạnh nhẫn nại chịu đựng giai đoạn khó lúc mới bắt đầu, thường để khuyên người mới. Khác 七転び八起き (đứng dậy sau thất bại) và 継続は力なり (làm đều đặn).","example":"石の上にも三年。もう少しこの仕事を続けてみます。","example_reading":"いしのうえにもさんねん。もうすこしこのしごとをつづけてみます。","example_meaning":"Kiên nhẫn sẽ có kết quả. Tôi sẽ thử làm công việc này thêm chút nữa.","level":"p1"},
{"word":"花より団子","reading":"はなよりだんご","meaning":"bánh trôi hơn hoa → Thích thực tế hơn vẻ đẹp bề ngoài","example":"花見でも、花より団子でお弁当ばかり食べている。","example_reading":"はなみでも、はなよりだんごでおべんとうばかりたべている。","example_meaning":"Đi ngắm hoa mà chỉ lo ăn cơm hộp, ăn hơn ngắm hoa.","level":"p1"},
{"word":"犬も歩けば棒に当たる","reading":"いぬもあるけばぼうにあたる","meaning":"chó đi cũng gặp gậy → Cứ hành động thì sẽ gặp chuyện may (hoặc rủi)","example":"犬も歩けば棒に当たる。散歩中に旧友に会った。","example_reading":"いぬもあるけばぼうにあたる。さんぽちゅうにきゅうゆうにあった。","example_meaning":"Cứ đi là gặp chuyện. Đi dạo thì gặp bạn cũ.","level":"p1"},
{"word":"二兎を追う者は一兎をも得ず","reading":"にとをおうものはいっとをもえず","meaning":"đuổi hai con thỏ thì không bắt được con nào → Tham thì thâm","example":"勉強とバイトを欲張って、二兎を追う者は一兎をも得ずだ。","example_reading":"べんきょうとバイトをよくばって、にとをおうものはいっとをもえずだ。","example_meaning":"Tham cả học lẫn làm thêm, hóa ra chẳng được cái nào.","level":"p1"},
{"word":"失敗は成功のもと","reading":"しっぱいはせいこうのもと","meaning":"thất bại là gốc của thành công → Thất bại là mẹ thành công","note":"⚠ Nhấn mạnh học được từ thất bại, hay dùng để an ủi. Khác 後悔先に立たず (đã lỡ rồi thì hối hận cũng không kịp).","example":"失敗は成功のもと。次は頑張ろう。","example_reading":"しっぱいはせいこうのもと。つぎはがんばろう。","example_meaning":"Thất bại là mẹ thành công. Lần sau cố gắng nhé.","level":"p1"},
{"word":"百聞は一見に如かず","reading":"ひゃくぶんはいっけんにしかず","meaning":"trăm nghe không bằng một thấy","note":"⚠ Khác 論より証拠: nhấn mạnh tận mắt thấy thì hiểu rõ hơn nghe kể, không phải chứng minh để thắng tranh luận.","example":"百聞は一見に如かずだ。実際に行ってみよう。","example_reading":"ひゃくぶんはいっけんにしかずだ。じっさいにいってみよう。","example_meaning":"Trăm nghe không bằng một thấy. Hãy đi xem thực tế.","level":"p1"},
{"word":"笑う門には福来る","reading":"わらうかどにはふくきたる","meaning":"nhà nào cười thì phúc đến","example":"笑う門には福来る。いつも笑顔でいよう。","example_reading":"わらうかどにはふくきたる。いつもえがおでいよう。","example_meaning":"Cười thì phúc đến. Hãy luôn mỉm cười.","level":"p1"},
{"word":"時は金なり","reading":"ときはかねなり","meaning":"thời gian là vàng bạc","example":"時は金なり。無駄な時間を減らそう。","example_reading":"ときはかねなり。むだなじかんをへらそう。","example_meaning":"Thời gian là vàng bạc. Hãy bớt phí thời gian.","level":"p1"},
{"word":"口は災いのもと","reading":"くちはわざわいのもと","meaning":"họa từ miệng mà ra","example":"口は災いのもと。言う前によく考えよう。","example_reading":"くちはわざわいのもと。いうまえによくかんがえよう。","example_meaning":"Họa từ miệng mà ra. Hãy nghĩ kỹ trước khi nói.","level":"p1"},
{"word":"備えあれば憂いなし","reading":"そなえあればうれいなし","meaning":"có chuẩn bị thì không lo → Phòng bệnh hơn chữa bệnh","note":"⚠ Dễ nhầm với 転ばぬ先の杖 và 石橋を叩いて渡る. Câu này nói chung về chuẩn bị trước thì khỏi lo.","example":"備えあれば憂いなし。防災グッズを用意しておこう。","example_reading":"そなえあればうれいなし。ぼうさいグッズをよういしておこう。","example_meaning":"Chuẩn bị sẵn thì không lo. Hãy chuẩn bị đồ phòng thiên tai.","level":"p1"},
{"word":"好きこそ物の上手なれ","reading":"すきこそもののじょうずなれ","meaning":"có thích mới giỏi","example":"好きこそ物の上手なれで、弟は絵がうまい。","example_reading":"すきこそもののじょうずなれで、おとうとはえがうまい。","example_meaning":"Vì thích nên em trai tôi vẽ giỏi.","level":"p1"},
{"word":"早起きは三文の徳","reading":"はやおきはさんもんのとく","meaning":"dậy sớm có lợi","example":"早起きは三文の徳。朝の散歩は気持ちがいい。","example_reading":"はやおきはさんもんのとく。あさのさんぽはきもちがいい。","example_meaning":"Dậy sớm có lợi. Đi dạo buổi sáng thật dễ chịu.","level":"p1"},
{"word":"終わり良ければ全て良し","reading":"おわりよければすべてよし","meaning":"kết thúc tốt thì mọi thứ đều tốt","example":"途中は大変だったが、終わり良ければ全て良しだ。","example_reading":"とちゅうはたいへんだったが、おわりよければすべてよしだ。","example_meaning":"Giữa chừng vất vả nhưng kết thúc tốt là được.","level":"p1"},
{"word":"鉄は熱いうちに打て","reading":"てつはあついうちにうて","meaning":"rèn sắt khi còn nóng → Làm đúng lúc, dạy dỗ khi còn trẻ","example":"鉄は熱いうちに打て。やる気がある今、勉強を始めよう。","example_reading":"てつはあついうちにうて。やるきがあるいま、べんきょうをはじめよう。","example_meaning":"Rèn sắt khi còn nóng. Giờ đang có hứng, hãy bắt đầu học.","level":"p1"},
{"word":"善は急げ","reading":"ぜんはいそげ","meaning":"việc tốt thì nên làm gấp → Việc hay nên làm ngay","example":"善は急げ。今日のうちに申し込もう。","example_reading":"ぜんはいそげ。きょうのうちにもうしこもう。","example_meaning":"Việc tốt nên làm ngay. Hãy đăng ký trong hôm nay.","level":"p1"},
{"word":"果報は寝て待て","reading":"かほうはねてまて","meaning":"phúc đến thì cứ nằm chờ → Việc không thể vội, hãy kiên nhẫn chờ thời","note":"⚠ Dễ nhầm với 待てば海路の日和あり. Câu này khuyên đừng sốt ruột, đã làm hết sức rồi thì cứ chờ.","example":"結果は果報は寝て待てだ。もう心配しないで。","example_reading":"けっかはかほうはねてまてだ。もうしんぱいしないで。","example_meaning":"Kết quả thì cứ bình tĩnh chờ. Đừng lo nữa.","level":"p1"},
{"word":"残り物には福がある","reading":"のこりものにはふくがある","meaning":"đồ còn sót lại có phúc → Người đến sau, đồ thừa lại đôi khi lại tốt","example":"残り物には福がある。最後に選んだ服が一番似合った。","example_reading":"のこりものにはふくがある。さいごにえらんだふくがいちばんにあった。","example_meaning":"Đồ còn lại có phúc. Chiếc áo chọn sau cùng lại hợp nhất.","level":"p1"},
{"word":"蛙の子は蛙","reading":"かえるのこはかえる","meaning":"con ếch là ếch → Con nhà nòi, con giống cha mẹ","note":"⚠ Ngược nghĩa với 鳶が鷹を生む. Đôi khi mang sắc thái chê: con cũng bình thường như cha mẹ.","example":"蛙の子は蛙で、父も息子も料理人だ。","example_reading":"かえるのこはかえるで、ちちもむすこもりょうりにんだ。","example_meaning":"Con nhà nòi, cả cha lẫn con đều là đầu bếp.","level":"p1"},
{"word":"親の心子知らず","reading":"おやのこころこしらず","meaning":"lòng cha mẹ con không biết → Con cái không hiểu nỗi lo của cha mẹ","example":"親の心子知らずで、息子は夜遅くまで遊んでいる。","example_reading":"おやのこころこしらずで、むすこはよるおそくまであそんでいる。","example_meaning":"Con không hiểu lòng cha mẹ, con trai tôi chơi tới khuya.","level":"p1"},
{"word":"かわいい子には旅をさせよ","reading":"かわいいこにはたびをさせよ","meaning":"thương con thì hãy cho đi xa → Thương con thì để con trải đời","example":"かわいい子には旅をさせよと言って、母は私を留学に送り出した。","example_reading":"かわいいこにはたびをさせよといって、はははわたしをりゅうがくにおくりだした。","example_meaning":"Mẹ nói thương con thì cho con đi xa, rồi tiễn tôi đi du học.","level":"p1"},
{"word":"親しき仲にも礼儀あり","reading":"したしきなかにもれいぎあり","meaning":"thân thiết cũng cần lễ nghi → Dù thân vẫn phải giữ lễ độ","example":"親しき仲にも礼儀あり。友達にも「ありがとう」を言おう。","example_reading":"したしきなかにもれいぎあり。ともだちにも「ありがとう」をいおう。","example_meaning":"Thân đến mấy cũng cần lễ phép. Với bạn bè cũng hãy nói cảm ơn.","level":"p1"},
{"word":"類は友を呼ぶ","reading":"るいはともをよぶ","meaning":"loại nào gặp loại đó → Cùng tính cách, sở thích thì tụ lại","example":"類は友を呼ぶで、サッカー好きが自然に集まった。","example_reading":"るいはともをよぶで、サッカーずきがしぜんにあつまった。","example_meaning":"Cùng loại thì tụ họp, những người mê bóng đá tự nhiên tụ lại.","level":"p1"},
{"word":"情けは人のためならず","reading":"なさけはひとのためならず","meaning":"làm ơn không phải vì người khác → Giúp người rồi sẽ được báo đáp lại","note":"⚠ Hay bị hiểu nhầm là 'giúp người ta sẽ làm hại họ'. Nghĩa đúng: lòng tốt cuối cùng sẽ quay về với mình.","example":"情けは人のためならず。困っている人を助けよう。","example_reading":"なさけはひとのためならず。こまっているひとをたすけよう。","example_meaning":"Giúp người là giúp mình. Hãy giúp người đang gặp khó.","level":"p1"},
{"word":"旅は道連れ世は情け","reading":"たびはみちづれよはなさけ","meaning":"đi đường có bạn, ở đời có tình → Con người cần nương tựa lẫn nhau","example":"旅は道連れ世は情けで、見知らぬ人が荷物を持ってくれた。","example_reading":"たびはみちづれよはなさけで、みしらぬひとがにもつをもってくれた。","example_meaning":"Đi đường cần bạn, ở đời cần tình người: một người lạ đã xách đồ giúp tôi.","level":"p1"},
{"word":"隣の花は赤い","reading":"となりのはなはあかい","meaning":"hoa nhà hàng xóm đỏ hơn → Của người khác trông luôn tốt hơn của mình","example":"隣の花は赤いで、友達の家がうらやましい。","example_reading":"となりのはなはあかいで、ともだちのいえがうらやましい。","example_meaning":"Hoa nhà bên đỏ hơn, tôi ghen tị với nhà bạn.","level":"p1"},
{"word":"縁の下の力持ち","reading":"えんのしたのちからもち","meaning":"người khỏe nâng bên dưới hiên → Người âm thầm gánh vác mà không ai thấy","example":"彼女は会社の縁の下の力持ちだ。","example_reading":"かのじょはかいしゃのえんのしたのちからもちだ。","example_meaning":"Cô ấy là người âm thầm gánh vác của công ty.","level":"p1"},
{"word":"損して得取れ","reading":"そんしてとくとれ","meaning":"chịu lỗ để lấy lời → Chịu thiệt trước để có lợi lâu dài","example":"損して得取れで、サービスで商品を一つ付けた。","example_reading":"そんしてとくとれで、サービスでしょうひんをひとつつけた。","example_meaning":"Chịu thiệt để có lợi lâu dài, tôi tặng kèm thêm một món.","level":"p1"},
{"word":"安物買いの銭失い","reading":"やすものがいのぜにうしない","meaning":"mua đồ rẻ mất tiền oan → Tiền nào của nấy","example":"安いくつはすぐ壊れた。安物買いの銭失いだ。","example_reading":"やすいくつはすぐこわれた。やすものがいのぜにうしないだ。","example_meaning":"Giày rẻ hỏng ngay. Mua đồ rẻ lại mất tiền.","level":"p1"},
{"word":"便りがないのは良い便り","reading":"たよりがないのはよいたより","meaning":"không có tin tức là tin tốt","example":"便りがないのは良い便りで、息子は元気にしているだろう。","example_reading":"たよりがないのはよいたよりで、むすこはげんきにしているだろう。","example_meaning":"Không tin tức là tin tốt, chắc con trai vẫn khỏe.","level":"p1"},
{"word":"一難去ってまた一難","reading":"いちなんさってまたいちなん","meaning":"qua một nạn lại gặp một nạn → Hết nạn này đến nạn khác","example":"試験が終わったら、今度は引っ越しだ。一難去ってまた一難だ。","example_reading":"しけんがおわったら、こんどはひっこしだ。いちなんさってまたいちなんだ。","example_meaning":"Thi xong thì giờ đến chuyển nhà. Hết nạn này đến nạn khác.","level":"p1"},
{"word":"命あっての物種","reading":"いのちあってのものだね","meaning":"có mạng mới có mọi thứ → Giữ mạng sống là quan trọng nhất","example":"台風のときは無理をしない。命あっての物種だ。","example_reading":"たいふうのときはむりをしない。いのちあってのものだねだ。","example_meaning":"Lúc có bão đừng liều. Còn mạng mới còn tất cả.","level":"p1"},
{"word":"病は気から","reading":"やまいはきから","meaning":"bệnh từ tâm mà ra → Tinh thần ảnh hưởng đến sức khỏe","example":"病は気からだ。明るい気持ちでいれば元気になる。","example_reading":"やまいはきからだ。あかるいきもちでいればげんきになる。","example_meaning":"Bệnh từ tâm. Giữ tinh thần vui vẻ thì sẽ khỏe.","level":"p1"},
{"word":"腹が減っては戦ができぬ","reading":"はらがへってはいくさができぬ","meaning":"bụng đói không đánh trận được → Có thực mới vực được đạo","example":"腹が減っては戦ができぬ。まず朝ごはんを食べよう。","example_reading":"はらがへってはいくさができぬ。まずあさごはんをたべよう。","example_meaning":"Có thực mới vực được đạo. Trước hết ăn sáng đã.","level":"p1"},
{"word":"腹八分目に医者いらず","reading":"はらはちぶんめにいしゃいらず","meaning":"ăn tám phần no thì khỏi cần thầy thuốc","example":"腹八分目に医者いらずだから、食べすぎないようにしている。","example_reading":"はらはちぶんめにいしゃいらずだから、たべすぎないようにしている。","example_meaning":"Ăn tám phần no khỏi cần thầy thuốc, nên tôi cố không ăn quá nhiều.","level":"p1"},
{"word":"言うは易く行うは難し","reading":"いうはやすくおこなうはかたし","meaning":"nói thì dễ, làm thì khó","example":"毎日運動するのは、言うは易く行うは難しだ。","example_reading":"まいにちうんどうするのは、いうはやすくおこなうはかたしだ。","example_meaning":"Tập thể dục mỗi ngày nói thì dễ, làm mới khó.","level":"p1"},
{"word":"思い立ったが吉日","reading":"おもいたったがきちじつ","meaning":"ngày nghĩ ra là ngày tốt → Muốn làm gì thì làm ngay","example":"思い立ったが吉日。今日からジョギングを始める。","example_reading":"おもいたったがきちじつ。きょうからジョギングをはじめる。","example_meaning":"Nghĩ ra là làm ngay. Từ hôm nay tôi bắt đầu chạy bộ.","level":"p1"},
{"word":"光陰矢の如し","reading":"こういんやのごとし","meaning":"thời gian như tên bay","example":"光陰矢の如しで、もう十二月だ。","example_reading":"こういんやのごとしで、もうじゅうにがつだ。","example_meaning":"Thời gian như tên bay, đã tháng Mười hai rồi.","level":"p1"},
{"word":"若い時の苦労は買ってでもせよ","reading":"わかいときのくろうはかってでもせよ","meaning":"gian khổ lúc trẻ thì mua cũng nên chịu → Khó nhọc thời trẻ là vốn quý","example":"若い時の苦労は買ってでもせよと祖父は言った。","example_reading":"わかいときのくろうはかってでもせよとそふはいった。","example_meaning":"Ông tôi nói gian khổ lúc trẻ là thứ nên tìm lấy.","level":"p1"},
{"word":"苦あれば楽あり","reading":"くあればらくあり","meaning":"có khổ thì có sướng","example":"苦あれば楽あり。試験の後は旅行に行こう。","example_reading":"くあればらくあり。しけんのあとはりょこうにいこう。","example_meaning":"Có khổ rồi sẽ có sướng. Thi xong đi du lịch nhé.","level":"p1"},
{"word":"禍を転じて福となす","reading":"わざわいをてんじてふくとなす","meaning":"chuyển họa thành phúc","example":"失敗を生かして、禍を転じて福となした。","example_reading":"しっぱいをいかして、わざわいをてんじてふくとなした。","example_meaning":"Tận dụng thất bại để chuyển họa thành phúc.","level":"p1"},
{"word":"捨てる神あれば拾う神あり","reading":"すてるかみあればひろうかみあり","meaning":"có thần bỏ thì có thần nhặt → Hết cửa này còn cửa khác","example":"面接に落ちたが、捨てる神あれば拾う神ありで、別の会社に決まった。","example_reading":"めんせつにおちたが、すてるかみあればひろうかみありで、べつのかいしゃにきまった。","example_meaning":"Trượt phỏng vấn nhưng hết cửa này còn cửa khác, tôi đậu công ty khác.","level":"p1"},
{"word":"知らぬが仏","reading":"しらぬがほとけ","meaning":"không biết thì là Phật → Không biết thì lòng thanh thản","example":"値段は知らぬが仏だ。聞かないでおこう。","example_reading":"ねだんはしらぬがほとけだ。きかないでおこう。","example_meaning":"Giá cả không biết thì khỏi lo. Đừng hỏi thì hơn.","level":"p1"},
{"word":"聞くは一時の恥、聞かぬは一生の恥","reading":"きくはいっときのはじ、きかぬはいっしょうのはじ","meaning":"hỏi chỉ xấu hổ nhất thời, không hỏi xấu hổ cả đời → Không biết thì cứ hỏi","example":"聞くは一時の恥、聞かぬは一生の恥。分からなければ質問しよう。","example_reading":"きくはいっときのはじ、きかぬはいっしょうのはじ。わからなければしつもんしよう。","example_meaning":"Hỏi chỉ xấu hổ một lúc. Không hiểu thì hãy hỏi.","level":"p1"},
{"word":"言わぬが花","reading":"いわぬがはな","meaning":"không nói ra mới đẹp → Có chuyện không nói ra thì hay hơn","example":"結果は言わぬが花だよ。","example_reading":"けっかはいわぬがはなだよ。","example_meaning":"Kết quả thì không nói ra thì hơn.","level":"p1"},
{"word":"壁に耳あり障子に目あり","reading":"かべにみみありしょうじにめあり","meaning":"tường có tai, cửa có mắt → Coi chừng bị nghe lén","example":"壁に耳あり障子に目あり。秘密の話は小さな声で。","example_reading":"かべにみみありしょうじにめあり。ひみつのはなしはちいさなこえで。","example_meaning":"Tường có tai. Chuyện bí mật hãy nói nhỏ.","level":"p1"},
{"word":"人の噂も七十五日","reading":"ひとのうわさもしちじゅうごにち","meaning":"tin đồn cũng chỉ kéo dài 75 ngày → Tin đồn rồi sẽ qua","example":"人の噂も七十五日だ。気にしなくていい。","example_reading":"ひとのうわさもしちじゅうごにちだ。きにしなくていい。","example_meaning":"Tin đồn rồi cũng qua. Đừng bận tâm.","level":"p1"},
{"word":"人の振り見て我が振り直せ","reading":"ひとのふりみてわがふりなおせ","meaning":"thấy người làm sai mà sửa mình","example":"人の振り見て我が振り直せ。マナーの悪い人を見て気をつけた。","example_reading":"ひとのふりみてわがふりなおせ。マナーのわるいひとをみてきをつけた。","example_meaning":"Nhìn người mà sửa mình. Thấy người vô ý tứ nên tôi tự nhắc mình.","level":"p1"},
{"word":"身から出た錆","reading":"みからでたさび","meaning":"gỉ sét từ chính thân mình → Tự làm tự chịu","example":"遅刻して怒られたのは身から出た錆だ。","example_reading":"ちこくしておこられたのはみからでたさびだ。","example_meaning":"Đi trễ bị mắng là tự làm tự chịu.","level":"p1"},
{"word":"蒔かぬ種は生えぬ","reading":"まかぬたねははえぬ","meaning":"hạt không gieo thì không mọc → Không làm thì không có kết quả","example":"蒔かぬ種は生えぬ。努力しなければ成果は出ない。","example_reading":"まかぬたねははえぬ。どりょくしなければせいかはでない。","example_meaning":"Không gieo thì không gặt. Không cố gắng thì không có kết quả.","level":"p1"},
{"word":"三つ子の魂百まで","reading":"みつごのたましいひゃくまで","meaning":"tính cách lúc ba tuổi đến trăm tuổi → Thói quen, bản tính từ nhỏ khó đổi","note":"⚠ Gần với 雀百まで踊り忘れず.","example":"三つ子の魂百まで。彼は子供の頃から本が好きだ。","example_reading":"みつごのたましいひゃくまで。かれはこどものころからほんがすきだ。","example_meaning":"Tính từ nhỏ khó đổi. Anh ấy thích sách từ bé.","level":"p1"},
{"word":"鬼に金棒","reading":"おににかなぼう","meaning":"quỷ cầm gậy sắt → Hổ mọc thêm cánh","example":"彼が仲間に加われば鬼に金棒だ。","example_reading":"かれがなかまにくわわればおににかなぼうだ。","example_meaning":"Có anh ấy tham gia thì như hổ mọc thêm cánh.","level":"p1"},
{"word":"二度あることは三度ある","reading":"にどあることはさんどある","meaning":"đã hai lần thì sẽ có lần thứ ba","example":"二度あることは三度あるから、気をつけて。","example_reading":"にどあることはさんどあるから、きをつけて。","example_meaning":"Đã xảy ra hai lần thì sẽ có lần ba, hãy cẩn thận.","level":"p1"},
{"word":"三度目の正直","reading":"さんどめのしょうじき","meaning":"lần thứ ba là chắc chắn → Thử lần ba thì thành","example":"三度目の正直で、ついに合格した。","example_reading":"さんどめのしょうじきで、ついにごうかくした。","example_meaning":"Lần thứ ba thì chắc ăn, cuối cùng tôi đã đậu.","level":"p1"},
{"word":"仏の顔も三度まで","reading":"ほとけのかおもさんどまで","meaning":"mặt Phật cũng chỉ ba lần → Kiên nhẫn cũng có giới hạn","example":"仏の顔も三度までだ。もう許さない。","example_reading":"ほとけのかおもさんどまでだ。もうゆるさない。","example_meaning":"Nhẫn nhịn cũng có giới hạn. Tôi không tha nữa.","level":"p1"},
{"word":"短気は損気","reading":"たんきはそんき","meaning":"nóng nảy chỉ thiệt thân","example":"短気は損気。落ち着いて話そう。","example_reading":"たんきはそんき。おちついてはなそう。","example_meaning":"Nóng nảy chỉ thiệt. Hãy bình tĩnh nói chuyện.","level":"p1"},
{"word":"急いては事を仕損じる","reading":"せいてはことをしそんじる","meaning":"vội vàng thì hỏng việc","note":"⚠ Gần 急がば回れ. Câu này nhấn mạnh vội thì hỏng; 急がば回れ khuyên chọn con đường chắc chắn.","example":"急いては事を仕損じる。ゆっくり確認しよう。","example_reading":"せいてはことをしそんじる。ゆっくりかくにんしよう。","example_meaning":"Vội thì hỏng việc. Hãy kiểm tra từ từ.","level":"p1"},
{"word":"焼け石に水","reading":"やけいしにみず","meaning":"nước đổ lên đá nóng → Muối bỏ bể, không đủ tác dụng","example":"千円の寄付では焼け石に水だ。","example_reading":"せんえんのきふではやけいしにみずだ。","example_meaning":"Quyên góp 1000 yên chỉ như muối bỏ bể.","level":"p1"},
{"word":"出る杭は打たれる","reading":"でるくいはうたれる","meaning":"cọc nhô lên bị đập xuống → Người nổi trội dễ bị ganh ghét","example":"出る杭は打たれると言うが、自分の意見を言おう。","example_reading":"でるくいはうたれるというが、じぶんのいけんをいおう。","example_meaning":"Người nổi trội dễ bị ghét, nhưng tôi vẫn nói ý kiến của mình.","level":"p1"},
{"word":"下手な鉄砲も数撃てば当たる","reading":"へたなてっぽうもかずうてばあたる","meaning":"súng dở bắn nhiều cũng trúng → Thử nhiều thì có lúc thành công","example":"下手な鉄砲も数撃てば当たる。たくさん応募しよう。","example_reading":"へたなてっぽうもかずうてばあたる。たくさんおうぼしよう。","example_meaning":"Bắn nhiều thế nào cũng trúng. Hãy nộp thật nhiều.","level":"p1"},
{"word":"棚からぼたもち","reading":"たなからぼたもち","meaning":"bánh ngọt từ trên kệ rơi xuống → Của trên trời rơi xuống","example":"友達にコンサートのチケットをもらった。棚からぼたもちだ。","example_reading":"ともだちにコンサートのチケットをもらった。たなからぼたもちだ。","example_meaning":"Bạn tặng vé hòa nhạc. Đúng là của trên trời rơi xuống.","level":"p1"},
{"word":"待てば海路の日和あり","reading":"まてばかいろのひよりあり","meaning":"chờ đợi sẽ có ngày biển yên → Kiên nhẫn chờ thì cơ hội sẽ đến","example":"待てば海路の日和あり。焦らないで。","example_reading":"まてばかいろのひよりあり。あせらないで。","example_meaning":"Chờ thì thời cơ sẽ đến. Đừng nóng vội.","level":"p1"},
{"word":"明日は明日の風が吹く","reading":"あしたはあしたのかぜがふく","meaning":"ngày mai gió ngày mai thổi → Chuyện mai tính sau, đừng lo trước","example":"明日は明日の風が吹く。今日はもう寝よう。","example_reading":"あしたはあしたのかぜがふく。きょうはもうねよう。","example_meaning":"Chuyện mai tính sau. Hôm nay đi ngủ thôi.","level":"p1"},
{"word":"一寸先は闇","reading":"いっすんさきはやみ","meaning":"trước mắt một tấc là bóng tối → Tương lai khó đoán","example":"一寸先は闇で、会社が突然なくなった。","example_reading":"いっすんさきはやみで、かいしゃがとつぜんなくなった。","example_meaning":"Tương lai khó đoán, công ty bỗng nhiên biến mất.","level":"p1"},
{"word":"塵も積もれば山となる","reading":"ちりもつもればやまとなる","meaning":"bụi tích lại thành núi → Tích tiểu thành đại","example":"毎日百円ずつ貯金している。塵も積もれば山となる。","example_reading":"まいにちひゃくえんずつちょきんしている。ちりもつもればやまとなる。","example_meaning":"Mỗi ngày tôi để dành 100 yên. Tích tiểu thành đại.","level":"p2"},
{"word":"雨降って地固まる","reading":"あめふってじかたまる","meaning":"mưa xong đất cứng → Sau sóng gió, quan hệ càng bền chặt","example":"喧嘩のあと、二人は仲良くなった。雨降って地固まるだ。","example_reading":"けんかのあと、ふたりはなかよくなった。あめふってじかたまるだ。","example_meaning":"Sau khi cãi nhau, hai người thân hơn. Sau mưa đất cứng lại.","level":"p2"},
{"word":"後悔先に立たず","reading":"こうかいさきにたたず","meaning":"hối hận không đến trước → Việc đã rồi hối cũng muộn","example":"勉強しておけばよかった。後悔先に立たずだ。","example_reading":"べんきょうしておけばよかった。こうかいさきにたたずだ。","example_meaning":"Giá mà đã học bài. Hối hận cũng muộn rồi.","level":"p2"},
{"word":"初心忘るべからず","reading":"しょしんわするべからず","meaning":"đừng quên tâm thế ban đầu","example":"仕事に慣れても、初心忘るべからずだ。","example_reading":"しごとになれても、しょしんわするべからずだ。","example_meaning":"Dù quen việc cũng đừng quên tâm thế ban đầu.","level":"p2"},
{"word":"論より証拠","reading":"ろんよりしょうこ","meaning":"bằng chứng hơn lý luận","note":"⚠ Dễ nhầm với 百聞は一見に如かず. Câu này dùng khi tranh cãi, bằng chứng thuyết phục hơn lý lẽ.","example":"論より証拠。実際に見せてください。","example_reading":"ろんよりしょうこ。じっさいにみせてください。","example_meaning":"Bằng chứng hơn lý luận. Hãy cho tôi xem thực tế.","level":"p2"},
{"word":"目は口ほどに物を言う","reading":"めはくちほどにものをいう","meaning":"mắt nói nhiều như miệng → Ánh mắt tiết lộ cảm xúc","example":"彼女は黙っていたが、目は口ほどに物を言うで、怒っているのが分かった。","example_reading":"かのじょはだまっていたが、めはくちほどにものをいうで、おこっているのがわかった。","example_meaning":"Cô ấy im lặng nhưng ánh mắt cho biết cô đang giận.","level":"p2"},
{"word":"腐っても鯛","reading":"くさってもたい","meaning":"cá tráp ôi vẫn là cá tráp → Voi chết vẫn còn tướng","example":"古いカメラだが、腐っても鯛で写真はきれいだ。","example_reading":"ふるいカメラだが、くさってもたいでしゃしんはきれいだ。","example_meaning":"Máy ảnh cũ nhưng vẫn là hàng tốt, ảnh vẫn đẹp.","level":"p2"},
{"word":"能ある鷹は爪を隠す","reading":"のうあるたかはつめをかくす","meaning":"chim ưng tài giỏi giấu móng → Người tài không khoe","example":"彼は能ある鷹は爪を隠すで、実は英語がとても上手だ。","example_reading":"かれはのうあるたかはつめをかくすで、じつはえいごがとてもじょうずだ。","example_meaning":"Anh ấy kín tiếng nhưng thật ra giỏi tiếng Anh.","level":"p2"},
{"word":"噂をすれば影","reading":"うわさをすればかげ","meaning":"nhắc đến thì bóng xuất hiện → Nhắc Tào Tháo, Tào Tháo đến","example":"噂をすれば影、ちょうど田中さんが来た。","example_reading":"うわさをすればかげ、ちょうどたなかさんがきた。","example_meaning":"Nhắc Tào Tháo, Tào Tháo đến: anh Tanaka vừa tới.","level":"p2"},
{"word":"虎穴に入らずんば虎子を得ず","reading":"こけつにいらずんばこじをえず","meaning":"không vào hang cọp sao bắt được cọp con → Không liều thì không được","example":"虎穴に入らずんば虎子を得ず。思い切って挑戦しよう。","example_reading":"こけつにいらずんばこじをえず。おもいきってちょうせんしよう。","example_meaning":"Không liều thì không được. Hãy mạnh dạn thử thách.","level":"p2"},
{"word":"良薬は口に苦し","reading":"りょうやくはくちににがし","meaning":"thuốc hay thì đắng → Lời khuyên thẳng thắn khó nghe nhưng có ích","example":"先生の注意は厳しいが、良薬は口に苦しだ。","example_reading":"せんせいのちゅういはきびしいが、りょうやくはくちににがしだ。","example_meaning":"Lời nhắc của thầy nghiêm khắc nhưng thuốc đắng dã tật.","level":"p2"},
{"word":"負けるが勝ち","reading":"まけるがかち","meaning":"thua là thắng → Nhường nhịn đôi khi lại có lợi","example":"喧嘩を避けるのも、負けるが勝ちだ。","example_reading":"けんかをさけるのも、まけるがかちだ。","example_meaning":"Tránh cãi nhau cũng là thua mà thành thắng.","level":"p2"},
{"word":"住めば都","reading":"すめばみやこ","meaning":"ở rồi thì đâu cũng là kinh đô → Ở lâu thành quen","example":"最初は不便だったが、住めば都で今は気に入っている。","example_reading":"さいしょはふべんだったが、すめばみやこでいまはきにいっている。","example_meaning":"Lúc đầu bất tiện nhưng ở quen rồi giờ tôi thích.","level":"p2"},
{"word":"三人寄れば文殊の知恵","reading":"さんにんよればもんじゅのちえ","meaning":"ba người tụm lại có trí tuệ như Văn Thù → Ba ông thợ da bằng Gia Cát","example":"三人寄れば文殊の知恵。みんなで考えよう。","example_reading":"さんにんよればもんじゅのちえ。みんなでかんがえよう。","example_meaning":"Nhiều người nghĩ chung sẽ có ý hay. Cùng suy nghĩ nào.","level":"p2"},
{"word":"郷に入っては郷に従え","reading":"ごうにいってはごうにしたがえ","meaning":"vào làng nào theo lệ làng đó → Nhập gia tùy tục","example":"日本に来たら、郷に入っては郷に従えでルールを守ろう。","example_reading":"にほんにきたら、ごうにいってはごうにしたがえでルールをまもろう。","example_meaning":"Đến Nhật thì nhập gia tùy tục, hãy tuân thủ quy tắc.","level":"p2"},
{"word":"溺れる者は藁をも掴む","reading":"おぼれるものはわらをもつかむ","meaning":"người chết đuối vớ cả rơm → Khi cùng đường thì bám bất cứ thứ gì","example":"溺れる者は藁をも掴む思いで、占いに頼った。","example_reading":"おぼれるものはわらをもつかむおもいで、うらないにたよった。","example_meaning":"Như người chết đuối vớ cọc, tôi đã dựa vào bói toán.","level":"p2"},
{"word":"医者の不養生","reading":"いしゃのふようじょう","meaning":"thầy thuốc không giữ gìn sức khỏe → Thầy thuốc không tự chữa mình","note":"⚠ Người giỏi về một lĩnh vực nhưng bản thân không làm theo điều mình khuyên. Khác 猿も木から落ちる (sai sót ngẫu nhiên).","example":"医者の不養生で、先生が風邪を引いた。","example_reading":"いしゃのふようじょうで、せんせいがかぜをひいた。","example_meaning":"Thầy thuốc mà lại bị cảm.","level":"p2"},
{"word":"灯台下暗し","reading":"とうだいもとくらし","meaning":"dưới chân đèn hải đăng thì tối → Điều gần nhất lại khó thấy","note":"⚠ Dễ nhầm với 木を見て森を見ず. Câu này: thứ ở gần mình lại không nhận ra (như tìm chìa khóa mãi mà nó ở ngay dưới bàn).","example":"灯台下暗しで、探していた鍵は机の下にあった。","example_reading":"とうだいもとくらしで、さがしていたかぎはつくえのしたにあった。","example_meaning":"Chìa khóa tôi tìm nằm ngay dưới bàn.","level":"p2"},
{"word":"転ばぬ先の杖","reading":"ころばぬさきのつえ","meaning":"gậy chống trước khi ngã → Phòng bệnh hơn chữa bệnh","note":"⚠ Giống 備えあれば憂いなし, nhưng nhấn mạnh việc đề phòng rủi ro trước khi xảy ra (bảo hiểm, nhắc nhở cẩn thận).","example":"転ばぬ先の杖で、旅行保険に入っておく。","example_reading":"ころばぬさきのつえで、りょこうほけんにはいっておく。","example_meaning":"Cẩn thận trước khi có chuyện, tôi mua bảo hiểm du lịch.","level":"p2"},
{"word":"石橋を叩いて渡る","reading":"いしばしをたたいてわたる","meaning":"gõ cầu đá rồi mới qua → Cẩn tắc vô áy náy","note":"⚠ Nói về TÍNH CÁCH rất cẩn trọng, đôi khi hơi quá mức. Khác 転ばぬ先の杖 (hành động đề phòng cụ thể).","example":"彼は石橋を叩いて渡る性格だ。","example_reading":"かれはいしばしをたたいてわたるせいかくだ。","example_meaning":"Anh ấy tính rất cẩn thận.","level":"p2"},
{"word":"一寸の虫にも五分の魂","reading":"いっすんのむしにもごぶのたましい","meaning":"con sâu nhỏ cũng có linh hồn → Nhỏ yếu cũng có lòng tự trọng","example":"一寸の虫にも五分の魂だ。子供でも馬鹿にしてはいけない。","example_reading":"いっすんのむしにもごぶのたましいだ。こどもでもばかにしてはいけない。","example_meaning":"Nhỏ yếu cũng có lòng tự trọng. Dù là trẻ con cũng không được coi thường.","level":"p2"},
{"word":"瓜の蔓に茄子はならぬ","reading":"うりのつるになすびはならぬ","meaning":"dây dưa không ra cà → Cha mẹ thế nào con thế ấy","note":"⚠ Cùng ý với 蛙の子は蛙, ngược 鳶が鷹を生む.","example":"瓜の蔓に茄子はならぬ。優秀な両親の子は優秀だ。","example_reading":"うりのつるになすびはならぬ。ゆうしゅうなりょうしんのこはゆうしゅうだ。","example_meaning":"Cha mẹ giỏi thì con cũng giỏi.","level":"p2"},
{"word":"子は鎹","reading":"こはかすがい","meaning":"con cái là cái móc nối vợ chồng","example":"子は鎹で、子供が生まれて夫婦の仲が戻った。","example_reading":"こはかすがいで、こどもがうまれてふうふのなかがもどった。","example_meaning":"Con là sợi dây gắn kết, có con rồi vợ chồng lại hòa thuận.","level":"p2"},
{"word":"後は野となれ山となれ","reading":"あとはのとなれやまとなれ","meaning":"sau này ra sao cũng mặc → Xong việc trước mắt thì mặc kệ hậu quả","example":"試験が終わったので、後は野となれ山となれだ。","example_reading":"しけんがおわったので、あとはのとなれやまとなれだ。","example_meaning":"Thi xong rồi, sau này ra sao thì ra.","level":"p2"},
{"word":"無理が通れば道理引っ込む","reading":"むりがとおればどうりひっこむ","meaning":"cái vô lý mà thắng thì lẽ phải phải lùi","example":"無理が通れば道理引っ込むで、不公平な決定になった。","example_reading":"むりがとおればどうりひっこむで、ふこうへいなけっていになった。","example_meaning":"Cái vô lý thắng thế nên có quyết định bất công.","level":"p2"},
{"word":"弱り目に祟り目","reading":"よわりめにたたりめ","meaning":"đã yếu lại gặp họa → Họa vô đơn chí","note":"⚠ Gần 泣きっ面に蜂, nhấn mạnh khi đang yếu, đang gặp khó thì lại thêm rắc rối.","example":"風邪を引いた日に財布をなくした。弱り目に祟り目だ。","example_reading":"かぜをひいたひにさいふをなくした。よわりめにたたりめだ。","example_meaning":"Ngày bị cảm lại làm mất ví. Họa vô đơn chí.","level":"p2"},
{"word":"少年老い易く学成り難し","reading":"しょうねんおいやすくがくなりがたし","meaning":"tuổi trẻ dễ qua, học thành tài khó → Hãy tranh thủ thời gian học","example":"少年老い易く学成り難し。時間を大切にしよう。","example_reading":"しょうねんおいやすくがくなりがたし。じかんをたいせつにしよう。","example_meaning":"Tuổi trẻ qua nhanh, học thành tài khó. Hãy quý thời gian.","level":"p2"},
{"word":"実るほど頭を垂れる稲穂かな","reading":"みのるほどこうべをたれるいなほかな","meaning":"lúa càng chín càng cúi đầu → Người càng giỏi càng khiêm tốn","example":"実るほど頭を垂れる稲穂かな。社長はいつも謙虚だ。","example_reading":"みのるほどこうべをたれるいなほかな。しゃちょうはいつもけんきょだ。","example_meaning":"Lúa chín càng cúi đầu. Giám đốc lúc nào cũng khiêm tốn.","level":"p2"},
{"word":"沈黙は金","reading":"ちんもくはきん","meaning":"im lặng là vàng","example":"沈黙は金。余計なことは言わない方がいい。","example_reading":"ちんもくはきん。よけいなことはいわないほうがいい。","example_meaning":"Im lặng là vàng. Đừng nói những điều thừa thì hơn.","level":"p2"},
{"word":"他山の石","reading":"たざんのいし","meaning":"đá của núi khác → Lấy sai lầm của người khác làm bài học cho mình","example":"友人の失敗を他山の石とする。","example_reading":"ゆうじんのしっぱいをたざんのいしとする。","example_meaning":"Tôi lấy thất bại của bạn làm bài học cho mình.","level":"p2"},
{"word":"玉磨かざれば光なし","reading":"たまみがかざればひかりなし","meaning":"ngọc không mài thì không sáng → Có tài mà không rèn luyện thì không thành","example":"玉磨かざれば光なし。毎日練習しよう。","example_reading":"たまみがかざればひかりなし。まいにちれんしゅうしよう。","example_meaning":"Ngọc không mài không sáng. Hãy luyện tập mỗi ngày.","level":"p2"},
{"word":"栴檀は双葉より芳し","reading":"せんだんはふたばよりかんばし","meaning":"cây đàn hương thơm từ lúc mới nảy mầm → Người tài lộ rõ từ nhỏ","example":"栴檀は双葉より芳しで、彼女は子供の頃から絵が上手だった。","example_reading":"せんだんはふたばよりかんばしで、かのじょはこどものころからえがじょうずだった。","example_meaning":"Người tài lộ rõ từ nhỏ, cô ấy vẽ giỏi từ bé.","level":"p2"},
{"word":"氏より育ち","reading":"うじよりそだち","meaning":"dòng dõi không bằng nuôi dạy → Môi trường nuôi dưỡng quan trọng hơn xuất thân","example":"氏より育ちと言うように、教育が大切だ。","example_reading":"うじよりそだちというように、きょういくがたいせつだ。","example_meaning":"Như người ta nói, nuôi dạy quan trọng hơn dòng dõi.","level":"p2"},
{"word":"虎の威を借る狐","reading":"とらのいをかるきつね","meaning":"cáo mượn oai hùm → Dựa hơi người có quyền thế","example":"社長の名前を使うなんて、虎の威を借る狐だ。","example_reading":"しゃちょうのなまえをつかうなんて、とらのいをかるきつねだ。","example_meaning":"Mượn tên giám đốc, đúng là cáo mượn oai hùm.","level":"p2"},
{"word":"鶴の一声","reading":"つるのひとこえ","meaning":"một tiếng của hạc → Một lời của người có quyền quyết định tất cả","example":"会議は長引いたが、社長の鶴の一声で決まった。","example_reading":"かいぎはながびいたが、しゃちょうのつるのひとこえできまった。","example_meaning":"Cuộc họp kéo dài nhưng một lời giám đốc là chốt.","level":"p2"},
{"word":"船頭多くして船山に登る","reading":"せんどうおおくしてふねやまにのぼる","meaning":"nhiều người lái thì thuyền lên núi → Lắm thầy thối ma","example":"意見が多すぎて、船頭多くして船山に登るだ。","example_reading":"いけんがおおすぎて、せんどうおおくしてふねやまにのぼるだ。","example_meaning":"Ý kiến nhiều quá, lắm thầy thối ma.","level":"p2"},
{"word":"暖簾に腕押し","reading":"のれんにうでおし","meaning":"đẩy tay vào tấm rèm → Chẳng có phản ứng gì, uổng công","note":"⚠ Giống 糠に釘 và 豆腐にかすがい: đều 'không có tác dụng'.","example":"何を言っても暖簾に腕押しだ。","example_reading":"なにをいってものれんにうでおしだ。","example_meaning":"Nói gì cũng như nước đổ lá khoai.","level":"p2"},
{"word":"糠に釘","reading":"ぬかにくぎ","meaning":"đóng đinh vào cám → Nói mãi cũng vô ích","example":"弟に何度言っても糠に釘だ。","example_reading":"おとうとになんどいってもぬかにくぎだ。","example_meaning":"Nói em trai bao nhiêu lần cũng vô ích.","level":"p2"},
{"word":"豆腐にかすがい","reading":"とうふにかすがい","meaning":"đóng móc vào đậu phụ → Không có tác dụng gì","example":"彼に説教しても、豆腐にかすがいだ。","example_reading":"かれにせっきょうしても、とうふにかすがいだ。","example_meaning":"Có khuyên anh ta cũng chẳng tác dụng gì.","level":"p2"},
{"word":"水清ければ魚棲まず","reading":"みずきよければうおすまず","meaning":"nước quá trong thì cá không sống → Quá nghiêm khắc thì không ai gần","example":"水清ければ魚棲まず。厳しすぎる上司には人が集まらない。","example_reading":"みずきよければうおすまず。きびしすぎるじょうしにはひとがあつまらない。","example_meaning":"Nước trong quá cá không sống. Sếp quá khắt khe thì không ai theo.","level":"p2"},
{"word":"紺屋の白袴","reading":"こうやのしろばかま","meaning":"thợ nhuộm mặc quần trắng → Giỏi nghề nhưng bỏ bê chính mình","note":"⚠ Gần 医者の不養生: người làm nghề lại không lo cho bản thân.","example":"美容師なのに自分の髪はぼさぼさ。紺屋の白袴だ。","example_reading":"びようしなのにじぶんのかみはぼさぼさ。こうやのしろばかまだ。","example_meaning":"Là thợ làm tóc mà tóc mình lại rối bù.","level":"p2"},
{"word":"坊主憎けりゃ袈裟まで憎い","reading":"ぼうずにくけりゃけさまでにくい","meaning":"ghét ông sư thì ghét luôn cái áo cà sa → Ghét ai thì ghét lây cả đồ của họ","example":"坊主憎けりゃ袈裟まで憎いで、彼が嫌いだから彼の家族まで嫌いだ。","example_reading":"ぼうずにくけりゃけさまでにくいで、かれがきらいだからかれのかぞくまできらいだ。","example_meaning":"Ghét người thì ghét lây, vì ghét anh ta nên ghét luôn cả gia đình anh ta.","level":"p2"},
{"word":"蓼食う虫も好き好き","reading":"たでくうむしもすきずき","meaning":"sâu ăn cỏ tade cũng có sở thích riêng → Mỗi người một sở thích","example":"蓼食う虫も好き好きだ。彼は辛い物が大好きだ。","example_reading":"たでくうむしもすきずきだ。かれはからいものがだいすきだ。","example_meaning":"Mỗi người một sở thích. Anh ấy cực thích đồ cay.","level":"p2"},
{"word":"長いものには巻かれろ","reading":"ながいものにはまかれろ","meaning":"gặp thế mạnh thì nên thuận theo","example":"長いものには巻かれろと思って、上司に従った。","example_reading":"ながいものにはまかれろとおもって、じょうしにしたがった。","example_meaning":"Nghĩ rằng nên theo thế mạnh nên tôi nghe theo sếp.","level":"p2"},
{"word":"寄らば大樹の陰","reading":"よらばたいじゅのかげ","meaning":"nấp dưới bóng cây lớn → Dựa vào chỗ mạnh thì an toàn","example":"寄らば大樹の陰で、大きい会社に就職した。","example_reading":"よらばたいじゅのかげで、おおきいかいしゃにしゅうしょくした。","example_meaning":"Dựa vào cây lớn cho chắc, tôi xin vào công ty lớn.","level":"p2"},
{"word":"弘法は筆を選ばず","reading":"こうぼうはふでをえらばず","meaning":"kōbō không chọn bút → Người giỏi không kén dụng cụ","note":"⚠ Khác 弘法にも筆の誤り (người giỏi cũng có lúc sai).","example":"弘法は筆を選ばず。彼は安いギターでも上手に弾く。","example_reading":"こうぼうはふでをえらばず。かれはやすいギターでもじょうずにひく。","example_meaning":"Người giỏi không kén dụng cụ. Anh ấy chơi giỏi cả với cây đàn rẻ.","level":"p2"},
{"word":"下手の横好き","reading":"へたのよこずき","meaning":"dở mà lại mê","example":"私は下手の横好きで、毎週ゴルフに行く。","example_reading":"わたしはへたのよこずきで、まいしゅうゴルフにいく。","example_meaning":"Tôi chơi dở mà mê, tuần nào cũng đi đánh golf.","level":"p2"},
{"word":"雀百まで踊り忘れず","reading":"すずめひゃくまでおどりわすれず","meaning":"chim sẻ trăm tuổi vẫn nhớ nhảy → Thói quen từ nhỏ khó bỏ","example":"雀百まで踊り忘れずで、祖母は今も早起きだ。","example_reading":"すずめひゃくまでおどりわすれずで、そぼはいまもはやおきだ。","example_meaning":"Thói quen khó bỏ, bà tôi bây giờ vẫn dậy sớm.","level":"p2"},
{"word":"年寄りの冷や水","reading":"としよりのひやみず","meaning":"người già tắm nước lạnh → Người già làm việc quá sức","example":"八十歳でマラソンなんて、年寄りの冷や水だよ。","example_reading":"はちじゅっさいでマラソンなんて、としよりのひやみずだよ。","example_meaning":"80 tuổi mà chạy marathon, người già làm quá sức rồi.","level":"p2"},
{"word":"亀の甲より年の功","reading":"かめのこうよりとしのこう","meaning":"kinh nghiệm tuổi tác hơn mai rùa → Gừng càng già càng cay","example":"亀の甲より年の功。祖母の知恵に助けられた。","example_reading":"かめのこうよりとしのこう。そぼのちえにたすけられた。","example_meaning":"Gừng càng già càng cay. Tôi được trí tuệ của bà giúp đỡ.","level":"p2"},
{"word":"老いては子に従え","reading":"おいてはこにしたがえ","meaning":"già thì nghe theo con","example":"老いては子に従えと言って、祖父は息子の意見を聞いた。","example_reading":"おいてはこにしたがえといって、そふはむすこのいけんをきいた。","example_meaning":"Ông nói già thì theo con nên đã nghe ý kiến của con trai.","level":"p2"},
{"word":"井の中の蛙大海を知らず","reading":"いのなかのかわずたいかいをしらず","meaning":"ếch ngồi đáy giếng không biết biển lớn → Hiểu biết hạn hẹp","example":"井の中の蛙大海を知らずだった。世界は広い。","example_reading":"いのなかのかわずたいかいをしらずだった。せかいはひろい。","example_meaning":"Tôi như ếch đáy giếng. Thế giới rộng lớn thật.","level":"p2"},
{"word":"窮鼠猫を噛む","reading":"きゅうそねこをかむ","meaning":"chuột cùng đường cắn mèo → Bị dồn vào đường cùng, kẻ yếu cũng phản kháng","example":"窮鼠猫を噛むで、弱いチームが強いチームに勝った。","example_reading":"きゅうそねこをかむで、よわいチームがつよいチームにかった。","example_meaning":"Chuột cùng đường cắn mèo, đội yếu đã thắng đội mạnh.","level":"p2"},
{"word":"角を矯めて牛を殺す","reading":"つのをためてうしをころす","meaning":"uốn sừng mà giết cả con trâu → Sửa khuyết điểm nhỏ mà hỏng cả cái lớn","example":"子供の欠点を直しすぎて、角を矯めて牛を殺すことになった。","example_reading":"こどものけってんをなおしすぎて、つのをためてうしをころすことになった。","example_meaning":"Sửa lỗi nhỏ của con quá mức khiến hỏng cả cái lớn.","level":"p2"},
{"word":"鶏口となるも牛後となるなかれ","reading":"けいこうとなるもぎゅうごとなるなかれ","meaning":"làm đầu gà còn hơn làm đuôi trâu","example":"小さい会社でも社長になる。鶏口となるも牛後となるなかれだ。","example_reading":"ちいさいかいしゃでもしゃちょうになる。けいこうとなるもぎゅうごとなるなかれだ。","example_meaning":"Làm đầu gà hơn đuôi trâu: dù công ty nhỏ tôi cũng muốn làm giám đốc.","level":"p2"},
{"word":"大は小を兼ねる","reading":"だいはしょうをかねる","meaning":"lớn dùng được cho cả nhỏ","example":"大は小を兼ねるから、大きいかばんを買った。","example_reading":"だいはしょうをかねるから、おおきいかばんをかった。","example_meaning":"Cái lớn dùng được cho cả nhỏ, nên tôi mua cái túi to.","level":"p2"},
{"word":"山椒は小粒でもぴりりと辛い","reading":"さんしょうはこつぶでもぴりりとからい","meaning":"hạt tiêu nhỏ nhưng cay xè → Người nhỏ bé nhưng tài giỏi","example":"山椒は小粒でもぴりりと辛い。小柄な選手が優勝した。","example_reading":"さんしょうはこつぶでもぴりりとからい。こがらなせんしゅがゆうしょうした。","example_meaning":"Nhỏ mà có võ. Cầu thủ nhỏ con đã vô địch.","level":"p2"},
{"word":"馬子にも衣装","reading":"まごにもいしょう","meaning":"người dắt ngựa mặc đẹp cũng ra dáng → Người đẹp vì lụa","example":"馬子にも衣装で、スーツを着たら立派に見える。","example_reading":"まごにもいしょうで、スーツをきたらりっぱにみえる。","example_meaning":"Người đẹp vì lụa, mặc vest vào trông bảnh bao.","level":"p2"},
{"word":"人は見かけによらぬもの","reading":"ひとはみかけによらぬもの","meaning":"không thể xét người qua vẻ bề ngoài","example":"人は見かけによらぬもので、怖そうな先生は優しかった。","example_reading":"ひとはみかけによらぬもので、こわそうなせんせいはやさしかった。","example_meaning":"Không thể xét người qua bề ngoài, thầy trông dữ lại rất hiền.","level":"p2"},
{"word":"衣食足りて礼節を知る","reading":"いしょくたりてれいせつをしる","meaning":"đủ ăn đủ mặc mới biết lễ nghĩa","example":"衣食足りて礼節を知る。生活が安定すると心に余裕が出る。","example_reading":"いしょくたりてれいせつをしる。せいかつがあんていするとこころによゆうがでる。","example_meaning":"Đủ ăn đủ mặc mới biết lễ nghĩa. Đời sống ổn định thì lòng thoải mái.","level":"p2"},
{"word":"貧乏暇なし","reading":"びんぼうひまなし","meaning":"nghèo thì không có thời gian rảnh","example":"貧乏暇なしで、毎日バイトで忙しい。","example_reading":"びんぼうひまなしで、まいにちバイトでいそがしい。","example_meaning":"Nghèo thì bận, ngày nào tôi cũng bận làm thêm.","level":"p2"},
{"word":"金は天下の回りもの","reading":"かねはてんかのまわりもの","meaning":"tiền xoay vòng khắp thiên hạ → Tiền lúc có lúc không","example":"金は天下の回りものだ。きっとまた入ってくる。","example_reading":"かねはてんかのまわりものだ。きっとまたはいってくる。","example_meaning":"Tiền bạc lúc có lúc không. Chắc chắn sẽ lại có.","level":"p2"},
{"word":"金の切れ目が縁の切れ目","reading":"かねのきれめがえんのきれめ","meaning":"hết tiền là hết duyên → Hết tiền thì quan hệ cũng chấm dứt","example":"金の切れ目が縁の切れ目で、友達が離れていった。","example_reading":"かねのきれめがえんのきれめで、ともだちがはなれていった。","example_meaning":"Hết tiền là hết duyên, bạn bè rời xa.","level":"p2"},
{"word":"地獄の沙汰も金次第","reading":"じごくのさたもかねしだい","meaning":"việc dưới địa ngục cũng tùy tiền → Có tiền mua tiên cũng được","example":"地獄の沙汰も金次第と言うが、お金がすべてではない。","example_reading":"じごくのさたもかねしだいというが、おかねがすべてではない。","example_meaning":"Có tiền mua tiên cũng được, nhưng tiền không phải tất cả.","level":"p2"},
{"word":"鳶が鷹を生む","reading":"とんびがたかをうむ","meaning":"diều hâu sinh ra đại bàng → Cha mẹ bình thường sinh con xuất chúng","note":"⚠ Ngược nghĩa với 蛙の子は蛙.","example":"普通の家なのに東大に入った。鳶が鷹を生むだ。","example_reading":"ふつうのいえなのにとうだいにはいった。とんびがたかをうむだ。","example_meaning":"Nhà bình thường mà con vào được Đại học Tokyo. Diều hâu sinh đại bàng.","level":"p2"},
{"word":"瓢箪から駒","reading":"ひょうたんからこま","meaning":"từ quả bầu chui ra con ngựa → Chuyện đùa hóa thật, điều bất ngờ","example":"冗談で応募したら当たった。瓢箪から駒だ。","example_reading":"じょうだんでおうぼしたらあたった。ひょうたんからこまだ。","example_meaning":"Đăng ký đùa mà trúng thật, đúng là chuyện bất ngờ.","level":"p2"},
{"word":"怪我の功名","reading":"けがのこうみょう","meaning":"lỡ tay mà thành công → Vô tình gặp may","example":"道に迷ったおかげで、いい店を見つけた。怪我の功名だ。","example_reading":"みちにまよったおかげで、いいみせをみつけた。けがのこうみょうだ。","example_meaning":"Nhờ lạc đường mà tìm được quán ngon. Lỡ mà hóa hay.","level":"p2"},
{"word":"柳に雪折れなし","reading":"やなぎにゆきおれなし","meaning":"cành liễu mềm không gãy vì tuyết → Mềm dẻo thì chịu được khó khăn","example":"柳に雪折れなし。柔軟に考えよう。","example_reading":"やなぎにゆきおれなし。じゅうなんにかんがえよう。","example_meaning":"Mềm dẻo thì không gãy. Hãy suy nghĩ linh hoạt.","level":"p2"},
{"word":"遠くの親戚より近くの他人","reading":"とおくのしんせきよりちかくのたにん","meaning":"họ hàng xa không bằng người dưng gần → Bán anh em xa, mua láng giềng gần","example":"遠くの親戚より近くの他人で、隣の人に助けてもらった。","example_reading":"とおくのしんせきよりちかくのたにんで、となりのひとにたすけてもらった。","example_meaning":"Bán anh em xa mua láng giềng gần, tôi được người hàng xóm giúp.","level":"p2"},
{"word":"朱に交われば赤くなる","reading":"しゅにまじわればあかくなる","meaning":"gần mực thì đen, gần đèn thì sáng","example":"朱に交われば赤くなる。友達は大切に選ぼう。","example_reading":"しゅにまじわればあかくなる。ともだちはたいせつにえらぼう。","example_meaning":"Gần mực thì đen. Hãy chọn bạn cẩn thận.","level":"p2"},
{"word":"河童の川流れ","reading":"かっぱのかわながれ","meaning":"kappa cũng bị nước cuốn → Người giỏi cũng có lúc sơ suất","note":"⚠ Giống 猿も木から落ちる, nhưng thường dùng khi người giỏi thất bại ngay ở sở trường của mình (như người bơi giỏi mà chết đuối).","example":"泳ぎが得意な彼が溺れかけるなんて、河童の川流れだ。","example_reading":"およぎがとくいなかれがおぼれかけるなんて、かっぱのかわながれだ。","example_meaning":"Người bơi giỏi mà suýt chìm, đúng là kappa cũng bị nước cuốn.","level":"p3"},
{"word":"木を見て森を見ず","reading":"きをみてもりをみず","meaning":"thấy cây mà không thấy rừng","note":"⚠ Khác 灯台下暗し: câu này nói chỉ nhìn chi tiết nhỏ mà mất cái nhìn toàn cảnh.","example":"細かい所ばかり見て、木を見て森を見ずになっている。","example_reading":"こまかいところばかりみて、きをみてもりをみずになっている。","example_meaning":"Chỉ chăm chăm chi tiết nên thành thấy cây mà không thấy rừng.","level":"p3"},
{"word":"柳の下にいつもどじょうはいない","reading":"やなぎのしたにいつもどじょうはいない","meaning":"không phải lúc nào dưới gốc liễu cũng có cá chạch → May một lần chưa chắc có lần hai","example":"前の成功は偶然だ。柳の下にいつもどじょうはいない。","example_reading":"まえのせいこうはぐうぜんだ。やなぎのしたにいつもどじょうはいない。","example_meaning":"Lần thành công trước là ngẫu nhiên, đâu phải lần nào cũng may.","level":"p3"},
{"word":"猫に小判","reading":"ねこにこばん","meaning":"tiền vàng cho mèo → Đàn gảy tai trâu","note":"⚠ Dễ nhầm với 豚に真珠 và 馬の耳に念仏. Dùng khi đưa VẬT có giá trị cho người không biết giá trị của nó nên vô ích. Giọng trung tính, đôi khi đùa. Ví dụ: tặng trẻ con máy ảnh đắt tiền.","example":"子供に高いカメラをあげても、猫に小判だ。","example_reading":"こどもにたかいカメラをあげても、ねこにこばんだ。","example_meaning":"Cho trẻ con máy ảnh đắt tiền thì đúng là phí của.","level":"p3"},
{"word":"豚に真珠","reading":"ぶたにしんじゅ","meaning":"ngọc trai cho heo → Ném ngọc cho heo","note":"⚠ Cùng ý với 猫に小判 (vật quý cho người không hiểu giá trị) nhưng nặng hơn, hơi coi thường người nhận. Hay dùng cho thứ đẹp, quý như ngọc, nghệ thuật. Không nên nói thẳng với người đối diện.","example":"音楽に興味がない人にCDを贈るのは、豚に真珠だ。","example_reading":"おんがくにきょうみがないひとにCDをおくるのは、ぶたにしんじゅだ。","example_meaning":"Tặng CD cho người không thích nhạc là phí công.","level":"p3"},
{"word":"泣きっ面に蜂","reading":"なきっつらにはち","meaning":"mặt đang khóc còn bị ong đốt → Họa vô đơn chí","example":"財布を落とした上に、電車に乗り遅れた。泣きっ面に蜂だ。","example_reading":"さいふをおとしたうえに、でんしゃにのりおくれた。なきっつらにはちだ。","example_meaning":"Đã rơi ví lại còn trễ tàu. Họa vô đơn chí.","level":"p3"},
{"word":"弘法にも筆の誤り","reading":"こうぼうにもふでのあやまり","meaning":"đến Kōbō cũng có lúc viết sai → Thánh cũng có lúc lầm","note":"⚠ Giống 猿も木から落ちる, nhưng dùng cho bậc thầy, người rất nổi tiếng mắc lỗi nhỏ. Kōbō là cao tăng nổi tiếng với thư pháp.","example":"弘法にも筆の誤りで、先生も計算を間違えた。","example_reading":"こうぼうにもふでのあやまりで、せんせいもけいさんをまちがえた。","example_meaning":"Đến thầy cũng tính sai, thánh cũng có lúc lầm.","level":"p3"},
{"word":"月とすっぽん","reading":"つきとすっぽん","meaning":"mặt trăng và con ba ba → Một trời một vực","example":"兄と私は、成績が月とすっぽんだ。","example_reading":"あにとわたしは、せいせきがつきとすっぽんだ。","example_meaning":"Điểm của anh tôi và tôi khác nhau một trời một vực.","level":"p3"},
{"word":"馬の耳に念仏","reading":"うまのみみにねんぶつ","meaning":"tụng kinh bên tai ngựa → Nước đổ lá khoai, đàn gảy tai trâu","note":"⚠ Khác 猫に小判 và 豚に真珠: câu này nói về LỜI NÓI (khuyên bảo, nhắc nhở) mà người nghe không để tâm, không dùng cho vật. Ví dụ: nhắc con mãi mà nó không nghe.","example":"弟に注意しても、馬の耳に念仏だ。","example_reading":"おとうとにちゅういしても、うまのみみにねんぶつだ。","example_meaning":"Nhắc em trai cũng như nước đổ lá khoai.","level":"p3"},
{"word":"立つ鳥跡を濁さず","reading":"たつとりあとをにごさず","meaning":"chim bay đi không làm đục chỗ cũ → Rời đi phải để lại gọn gàng","example":"立つ鳥跡を濁さず。退職前に机をきれいにした。","example_reading":"たつとりあとをにごさず。たいしょくまえにつくえをきれいにした。","example_meaning":"Trước khi nghỉ việc, tôi dọn sạch bàn làm việc.","level":"p3"},
{"word":"触らぬ神に祟りなし","reading":"さわらぬかみにたたりなし","meaning":"không đụng vào thần thì không bị quở → Không dây vào thì không rắc rối","example":"触らぬ神に祟りなしで、その話には関わらないことにした。","example_reading":"さわらぬかみにたたりなしで、そのはなしにはかかわらないことにした。","example_meaning":"Không dây vào thì không rắc rối, nên tôi quyết định không liên quan đến chuyện đó.","level":"p3"},
{"word":"君子危うきに近寄らず","reading":"くんしあやうきにちかよらず","meaning":"người khôn không đến gần chỗ nguy hiểm","example":"君子危うきに近寄らず。夜の暗い道は通らない。","example_reading":"くんしあやうきにちかよらず。よるのくらいみちはとおらない。","example_meaning":"Người khôn tránh chỗ nguy hiểm. Tôi không đi đường tối ban đêm.","level":"p3"},
{"word":"藪をつついて蛇を出す","reading":"やぶをつついてへびをだす","meaning":"đập bụi rậm làm rắn chui ra → Chọc vào chuyện không cần, rước họa","example":"余計な質問をして、藪をつついて蛇を出した。","example_reading":"よけいなしつもんをして、やぶをつついてへびをだした。","example_meaning":"Hỏi chuyện thừa nên chọc rắn ra khỏi bụi, rước họa vào thân.","level":"p3"},
{"word":"藪から棒","reading":"やぶからぼう","meaning":"gậy từ trong bụi thò ra → Đột ngột, bất ngờ","note":"⚠ Thường dùng dạng 藪から棒に + động từ.","example":"藪から棒に「結婚する」と言われて驚いた。","example_reading":"やぶからぼうに「けっこんする」といわれておどろいた。","example_meaning":"Bỗng dưng nghe nói 'tôi sẽ kết hôn' làm tôi giật mình.","level":"p3"},
{"word":"酒は百薬の長","reading":"さけはひゃくやくのちょう","meaning":"rượu là đứng đầu trăm loại thuốc → Uống vừa phải thì tốt","example":"酒は百薬の長と言うが、飲みすぎはよくない。","example_reading":"さけはひゃくやくのちょうというが、のみすぎはよくない。","example_meaning":"Rượu là thuốc bổ nhưng uống quá thì không tốt.","level":"p3"},
{"word":"敵に塩を送る","reading":"てきにしおをおくる","meaning":"gửi muối cho kẻ địch → Giúp đỡ đối thủ lúc họ gặp khó","example":"敵に塩を送る気持ちで、ライバルにアドバイスをした。","example_reading":"てきにしおをおくるきもちで、ライバルにアドバイスをした。","example_meaning":"Với tinh thần gửi muối cho đối thủ, tôi đã khuyên đối thủ.","level":"p3"},
{"word":"勝って兜の緒を締めよ","reading":"かってかぶとのおをしめよ","meaning":"thắng rồi vẫn siết chặt dây mũ giáp → Thắng rồi cũng không được chủ quan","example":"勝って兜の緒を締めよ。次の試合も油断しない。","example_reading":"かってかぶとのおをしめよ。つぎのしあいもゆだんしない。","example_meaning":"Thắng rồi cũng không chủ quan. Trận sau cũng không lơ là.","level":"p3"},
{"word":"一事が万事","reading":"いちじがばんじ","meaning":"một việc nhìn ra mọi việc → Nhìn một việc nhỏ biết được toàn bộ","example":"一事が万事で、彼は小さな約束も守らない。","example_reading":"いちじがばんじで、かれはちいさなやくそくもまもらない。","example_meaning":"Nhìn một việc biết hết, anh ta ngay cả lời hứa nhỏ cũng không giữ.","level":"p3"},
{"word":"骨折り損のくたびれ儲け","reading":"ほねおりぞんのくたびれもうけ","meaning":"mất công mà chỉ được mệt → Uổng công vô ích","example":"一日探したが見つからなかった。骨折り損のくたびれ儲けだ。","example_reading":"いちにちさがしたがみつからなかった。ほねおりぞんのくたびれもうけだ。","example_meaning":"Tìm cả ngày không thấy. Chỉ tổ uổng công.","level":"p3"},
{"word":"夫婦喧嘩は犬も食わない","reading":"ふうふげんかはいぬもくわない","meaning":"vợ chồng cãi nhau chó cũng không thèm ăn → Chuyện vợ chồng đừng can thiệp","example":"夫婦喧嘩は犬も食わないから、放っておこう。","example_reading":"ふうふげんかはいぬもくわないから、ほうっておこう。","example_meaning":"Vợ chồng cãi nhau thì kệ họ đi.","level":"p3"},
{"word":"仏作って魂入れず","reading":"ほとけつくってたましいいれず","meaning":"làm tượng Phật mà quên khai quang → Làm xong phần hình thức nhưng thiếu cái cốt lõi","example":"立派な計画だが実行しなければ、仏作って魂入れずだ。","example_reading":"りっぱなけいかくだがじっこうしなければ、ほとけつくってたましいいれずだ。","example_meaning":"Kế hoạch hay mà không thực hiện thì chỉ có vỏ không có hồn.","level":"p3"},
{"word":"嘘も方便","reading":"うそもほうべん","meaning":"nói dối cũng là phương tiện → Đôi khi nói dối vì mục đích tốt","example":"嘘も方便で、「おいしいね」と言った。","example_reading":"うそもほうべんで、「おいしいね」といった。","example_meaning":"Nói dối vì mục đích tốt, tôi nói 'ngon nhỉ'.","level":"p3"},
{"word":"嘘つきは泥棒の始まり","reading":"うそつきはどろぼうのはじまり","meaning":"nói dối là bước đầu của trộm cắp → Nói dối là khởi đầu của điều xấu","example":"嘘つきは泥棒の始まりだ。正直に話しなさい。","example_reading":"うそつきはどろぼうのはじまりだ。しょうじきにはなしなさい。","example_meaning":"Nói dối là khởi đầu của tội lỗi. Hãy nói thật.","level":"p3"},
{"word":"一年の計は元旦にあり","reading":"いちねんのけいはがんたんにあり","meaning":"kế hoạch cả năm bắt đầu từ ngày đầu năm","example":"一年の計は元旦にあり。今年の目標を書こう。","example_reading":"いちねんのけいはがんたんにあり。ことしのもくひょうをかこう。","example_meaning":"Kế hoạch năm bắt đầu từ ngày đầu năm. Hãy viết mục tiêu năm nay.","level":"p3"},
{"word":"百里を行く者は九十里を半ばとす","reading":"ひゃくりをゆくものはくじゅうりをなかばとす","meaning":"người đi trăm dặm coi chín mươi dặm mới là nửa đường → Gần xong cũng đừng lơ là","example":"百里を行く者は九十里を半ばとす。最後まで気を抜かない。","example_reading":"ひゃくりをゆくものはくじゅうりをなかばとす。さいごまできをぬかない。","example_meaning":"Gần tới đích mới là nửa đường. Đừng lơ là đến phút cuối.","level":"p3"},
{"word":"勝てば官軍","reading":"かてばかんぐん","meaning":"thắng thì là quan quân → Thắng thì làm gì cũng đúng, thua mới là sai","example":"勝てば官軍と言うが、ずるい方法はよくない。","example_reading":"かてばかんぐんというが、ずるいほうほうはよくない。","example_meaning":"Thắng làm vua nhưng dùng cách gian lận thì không tốt.","level":"p3"},
{"word":"勝負は時の運","reading":"しょうぶはときのうん","meaning":"thắng thua do vận may nhất thời","example":"勝負は時の運だ。負けても気にしない。","example_reading":"しょうぶはときのうんだ。まけてもきにしない。","example_meaning":"Thắng thua do vận. Thua cũng không bận tâm.","level":"p3"},
{"word":"帯に短し襷に長し","reading":"おびにみじかしたすきにながし","meaning":"làm đai thì ngắn, làm dây buộc tay áo thì dài → Nửa vời, không hợp việc nào","example":"この机は帯に短し襷に長しで、部屋に合わない。","example_reading":"このつくえはおびにみじかしたすきにながしで、へやにあわない。","example_meaning":"Cái bàn này nửa vời, không hợp với căn phòng.","level":"p3"},
{"word":"二階から目薬","reading":"にかいからめぐすり","meaning":"nhỏ thuốc mắt từ tầng hai → Làm việc xa vời, không hiệu quả","example":"メールで謝るだけでは二階から目薬だ。","example_reading":"メールであやまるだけではにかいからめぐすりだ。","example_meaning":"Chỉ xin lỗi qua email thì chẳng ăn thua.","level":"p3"},
{"word":"海老で鯛を釣る","reading":"えびでたいをつる","meaning":"dùng tôm câu cá tráp → Bỏ ít vốn, thu nhiều lợi","example":"小さなプレゼントで大きな契約が取れた。海老で鯛を釣るだ。","example_reading":"ちいさなプレゼントでおおきなけいやくがとれた。えびでたいをつるだ。","example_meaning":"Tặng quà nhỏ mà được hợp đồng lớn. Bỏ con tép bắt con tôm.","level":"p3"},
{"word":"取らぬ狸の皮算用","reading":"とらぬたぬきのかわざんよう","meaning":"tính tiền da lửng khi chưa bắt được → Tính toán trước khi chắc chắn","example":"宝くじが当たる前に使い道を考えるのは、取らぬ狸の皮算用だ。","example_reading":"たからくじがあたるまえにつかいみちをかんがえるのは、とらぬたぬきのかわざんようだ。","example_meaning":"Chưa trúng xổ số đã nghĩ cách tiêu tiền là tính chuyện chưa chắc.","level":"p3"},
{"word":"縁は異なもの味なもの","reading":"えんはいなものあじなもの","meaning":"duyên số thật kỳ lạ và thú vị","example":"縁は異なもの味なもの。二人は海外で出会った。","example_reading":"えんはいなものあじなもの。ふたりはかいがいでであった。","example_meaning":"Duyên thật kỳ diệu. Hai người đã gặp nhau ở nước ngoài.","level":"p3"},
{"word":"虻蜂取らず","reading":"あぶはちとらず","meaning":"đuổi cả ruồi trâu lẫn ong, chẳng được con nào → Tham thì thâm","note":"⚠ Gần 二兎を追う者は一兎をも得ず, nghĩa gần như giống nhau.","example":"欲張ると虻蜂取らずになるよ。","example_reading":"よくばるとあぶはちとらずになるよ。","example_meaning":"Tham quá thì chẳng được gì đâu.","level":"p3"},
{"word":"頭隠して尻隠さず","reading":"あたまかくしてしりかくさず","meaning":"giấu đầu mà hở đuôi","example":"隠れたつもりでも、頭隠して尻隠さずだ。","example_reading":"かくれたつもりでも、あたまかくしてしりかくさずだ。","example_meaning":"Dù tưởng đã giấu, vẫn là giấu đầu hở đuôi.","level":"p3"},
{"word":"薬も過ぎれば毒となる","reading":"くすりもすぎればどくとなる","meaning":"thuốc dùng quá liều cũng thành độc","example":"薬も過ぎれば毒となる。決められた量を飲もう。","example_reading":"くすりもすぎればどくとなる。きめられたりょうをのもう。","example_meaning":"Thuốc quá liều cũng thành độc. Hãy uống đúng liều.","level":"p3"},
{"word":"過ぎたるは猶及ばざるが如し","reading":"すぎたるはなおおよばざるがごとし","meaning":"quá mức cũng như chưa đến → Cái gì quá cũng không tốt","example":"過ぎたるは猶及ばざるが如し。勉強も休むことが大切だ。","example_reading":"すぎたるはなおおよばざるがごとし。べんきょうもやすむことがたいせつだ。","example_meaning":"Quá mức cũng không tốt. Học cũng cần nghỉ ngơi.","level":"p3"},
{"word":"柔よく剛を制す","reading":"じゅうよくごうをせいす","meaning":"mềm thắng cứng","example":"柔よく剛を制すで、小さい選手が大きい選手を投げた。","example_reading":"じゅうよくごうをせいすで、ちいさいせんしゅがおおきいせんしゅをなげた。","example_meaning":"Mềm thắng cứng, võ sĩ nhỏ đã quật ngã võ sĩ to.","level":"p3"},
{"word":"憎まれっ子世にはばかる","reading":"にくまれっこよにはばかる","meaning":"người bị ghét lại sống lâu, thành đạt","example":"憎まれっ子世にはばかるで、あの人は意外と長生きだ。","example_reading":"にくまれっこよにはばかるで、あのひとはいがいとながいきだ。","example_meaning":"Người bị ghét lại sống lâu, ông ấy bất ngờ sống rất thọ.","level":"p3"},
{"word":"可愛さ余って憎さ百倍","reading":"かわいさあまってにくさひゃくばい","meaning":"thương nhiều thì khi giận càng ghét gấp trăm lần","example":"可愛さ余って憎さ百倍で、裏切られて強く怒った。","example_reading":"かわいさあまってにくさひゃくばいで、うらぎられてつよくおこった。","example_meaning":"Yêu nhiều nên khi bị phản bội thì giận dữ khôn tả.","level":"p3"},
{"word":"恩を仇で返す","reading":"おんをあだでかえす","meaning":"lấy oán trả ơn","example":"助けてもらったのに悪口を言うなんて、恩を仇で返すことだ。","example_reading":"たすけてもらったのにわるぐちをいうなんて、おんをあだでかえすことだ。","example_meaning":"Được giúp mà còn nói xấu, thật là lấy oán trả ơn.","level":"p3"},
{"word":"飼い犬に手を噛まれる","reading":"かいいぬにてをかまれる","meaning":"bị chó nhà cắn → Bị người mình tin tưởng phản bội","example":"部下に裏切られて、飼い犬に手を噛まれた。","example_reading":"ぶかにうらぎられて、かいいぬにてをかまれた。","example_meaning":"Bị cấp dưới phản bội, đúng là nuôi ong tay áo.","level":"p3"},
{"word":"先んずれば人を制す","reading":"さきんずればひとをせいす","meaning":"ra tay trước thì chế ngự được người","example":"先んずれば人を制す。早めに準備しよう。","example_reading":"さきんずればひとをせいす。はやめにじゅんびしよう。","example_meaning":"Ra tay trước thì chiếm ưu thế. Hãy chuẩn bị sớm.","level":"p3"},
{"word":"人事を尽くして天命を待つ","reading":"じんじをつくしててんめいをまつ","meaning":"làm hết sức rồi chờ ý trời","example":"人事を尽くして天命を待つ。後は結果を待つだけだ。","example_reading":"じんじをつくしててんめいをまつ。あとはけっかをまつだけだ。","example_meaning":"Làm hết sức rồi chờ ý trời. Giờ chỉ còn chờ kết quả.","level":"p3"},
{"word":"天は自ら助くる者を助く","reading":"てんはみずからたすくるものをたすく","meaning":"trời giúp người biết tự giúp mình","example":"天は自ら助くる者を助く。まず自分で努力しよう。","example_reading":"てんはみずからたすくるものをたすく。まずじぶんでどりょくしよう。","example_meaning":"Trời giúp người tự giúp mình. Trước hết hãy tự cố gắng.","level":"p3"},
{"word":"天災は忘れた頃にやってくる","reading":"てんさいはわすれたころにやってくる","meaning":"thiên tai đến khi người ta đã quên","example":"天災は忘れた頃にやってくる。避難訓練を続けよう。","example_reading":"てんさいはわすれたころにやってくる。ひなんくんれんをつづけよう。","example_meaning":"Thiên tai đến lúc ta quên. Hãy tiếp tục diễn tập sơ tán.","level":"p3"},
{"word":"火のない所に煙は立たぬ","reading":"ひのないところにけむりはたたぬ","meaning":"không có lửa làm sao có khói","example":"火のない所に煙は立たぬ。噂には何か理由があるはずだ。","example_reading":"ひのないところにけむりはたたぬ。うわさにはなにかりゆうがあるはずだ。","example_meaning":"Không có lửa sao có khói. Tin đồn chắc có lý do.","level":"p3"},
{"word":"鵜の真似をする烏","reading":"うのまねをするからす","meaning":"quạ bắt chước chim cốc → Bắt chước người giỏi mà hỏng việc","example":"兄の真似をして失敗した。鵜の真似をする烏だ。","example_reading":"あにのまねをしてしっぱいした。うのまねをするからすだ。","example_meaning":"Bắt chước anh trai mà thất bại, đúng là quạ bắt chước chim cốc.","level":"p3"},
{"word":"一を聞いて十を知る","reading":"いちをきいてじゅうをしる","meaning":"nghe một biết mười → Rất thông minh","example":"彼女は一を聞いて十を知る頭のいい人だ。","example_reading":"かのじょはいちをきいてじゅうをしるあたまのいいひとだ。","example_meaning":"Cô ấy thông minh, nghe một biết mười.","level":"p3"},
{"word":"寝る子は育つ","reading":"ねるこはそだつ","meaning":"trẻ ngủ nhiều thì lớn nhanh","example":"寝る子は育つ。早く寝なさい。","example_reading":"ねるこはそだつ。はやくねなさい。","example_meaning":"Trẻ ngủ nhiều thì lớn. Đi ngủ sớm đi.","level":"p3"},
{"word":"武士は食わねど高楊枝","reading":"ぶしはくわねどたかようじ","meaning":"võ sĩ không ăn vẫn ngậm tăm → Nghèo vẫn giữ sĩ diện","example":"武士は食わねど高楊枝で、お金がなくても平気な顔をしている。","example_reading":"ぶしはくわねどたかようじで、おかねがなくてもへいきなかおをしている。","example_meaning":"Nghèo vẫn giữ sĩ diện, không có tiền mà vẫn tỏ ra bình thản.","level":"p3"},
{"word":"負うた子に教えられて浅瀬を渡る","reading":"おうたこにおしえられてあさせをわたる","meaning":"được đứa trẻ cõng trên lưng chỉ chỗ nông qua sông → Đôi khi học được từ người nhỏ tuổi hơn","example":"負うた子に教えられて浅瀬を渡る。若い社員にパソコンを教わった。","example_reading":"おうたこにおしえられてあさせをわたる。わかいしゃいんにパソコンをおそわった。","example_meaning":"Có khi học được từ người trẻ. Tôi được nhân viên trẻ chỉ cách dùng máy tính.","level":"p3"},
{"word":"立っている者は親でも使え","reading":"たっているものはおやでもつかえ","meaning":"người đang đứng thì cha mẹ cũng nhờ → Cần là nhờ ngay người ở gần","example":"立っている者は親でも使えで、近くにいた人に頼んだ。","example_reading":"たっているものはおやでもつかえで、ちかくにいたひとにたのんだ。","example_meaning":"Cần là nhờ ngay, tôi nhờ người đứng gần đó.","level":"p3"},
{"word":"魚心あれば水心","reading":"うおごころあればみずごころ","meaning":"cá có lòng thì nước có tình → Có thiện ý thì sẽ được đáp lại","example":"魚心あれば水心で、こちらが親切にすれば相手も協力してくれる。","example_reading":"うおごころあればみずごころで、こちらがしんせつにすればあいてもきょうりょくしてくれる。","example_meaning":"Mình tử tế thì đối phương cũng hợp tác.","level":"p3"},
{"word":"渡る世間に鬼はなし","reading":"わたるせけんにおにはなし","meaning":"ở đời không có quỷ dữ → Thế gian vẫn có người tốt","example":"渡る世間に鬼はなし。困っていたら見知らぬ人が助けてくれた。","example_reading":"わたるせけんにおにはなし。こまっていたらみしらぬひとがたすけてくれた。","example_meaning":"Ở đời vẫn có người tốt. Khi tôi gặp khó, người lạ đã giúp.","level":"p3"},
{"word":"論語読みの論語知らず","reading":"ろんごよみのろんごしらず","meaning":"đọc Luận Ngữ mà không hiểu Luận Ngữ → Biết sách vở mà không làm theo","example":"論語読みの論語知らずで、知識はあるが行動が伴わない。","example_reading":"ろんごよみのろんごしらずで、ちしきはあるがこうどうがともなわない。","example_meaning":"Biết lý thuyết mà không làm theo: có kiến thức nhưng hành động không đi kèm.","level":"p3"},
{"word":"雨垂れ石を穿つ","reading":"あまだれいしをうがつ","meaning":"giọt nước nhỏ lâu ngày xuyên đá → Kiên trì thì việc khó cũng thành","note":"⚠ Gần 継続は力なり, nhấn mạnh sức mạnh của sự tích lũy nhỏ bền bỉ.","example":"雨垂れ石を穿つ。毎日練習すれば上手になる。","example_reading":"あまだれいしをうがつ。まいにちれんしゅうすればじょうずになる。","example_meaning":"Nước chảy đá mòn. Luyện tập mỗi ngày sẽ giỏi.","level":"p3"},
{"word":"蟻の穴から堤も崩れる","reading":"ありのあなからつつみもくずれる","meaning":"từ lỗ kiến mà đê cũng sập → Sơ suất nhỏ gây họa lớn","example":"蟻の穴から堤も崩れる。小さなミスにも注意しよう。","example_reading":"ありのあなからつつみもくずれる。ちいさなミスにもちゅういしよう。","example_meaning":"Lỗ kiến làm sập đê. Hãy chú ý cả lỗi nhỏ.","level":"p3"},
{"word":"所変われば品変わる","reading":"ところかわればしなかわる","meaning":"nơi khác thì phong tục, đồ vật cũng khác","example":"所変われば品変わるで、地域ごとにお雑煮が違う。","example_reading":"ところかわればしなかわるで、ちいきごとにおぞうにがちがう。","example_meaning":"Mỗi vùng mỗi khác, món ozoni mỗi nơi một kiểu.","level":"p3"},
{"word":"枯れ木も山の賑わい","reading":"かれきもやまのにぎわい","meaning":"cây khô cũng làm núi thêm náo nhiệt → Có thêm người cũng thêm vui","note":"⚠ Thường dùng khiêm tốn khi nói về bản thân mình tham gia.","example":"枯れ木も山の賑わいですから、私も参加します。","example_reading":"かれきもやまのにぎわいですから、わたしもさんかします。","example_meaning":"Có thêm người cho đông vui, tôi cũng xin tham gia.","level":"p3"},
{"word":"蛙の面に水","reading":"かえるのつらにみず","meaning":"nước đổ mặt ếch → Mặc kệ, thản nhiên không biết xấu hổ","example":"叱られても蛙の面に水で、全然気にしない。","example_reading":"しかられてもかえるのつらにみずで、ぜんぜんきにしない。","example_meaning":"Bị mắng mà vẫn thản nhiên, hoàn toàn không để tâm.","level":"p3"}
],
"grammar": []
};
